import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Soft-delete conventions.
 *
 * Archiving stamps `archived_at` instead of removing the row. An archived
 * issue stays restorable until the workspace plan's `retentionDays` have
 * elapsed (a multiple of 24h); the retention sweep then deletes it for good.
 * Repositories must express "live rows only" through these helpers so the
 * predicate stays in one place; a raw `isNull(table.archivedAt)` sprinkled
 * through the data layer is exactly the drift this module prevents.
 */

/**
 * Instant at which an archive becomes expired. An `archivedAt` at or before
 * this cut-off has had at least `retentionDays` × 24h pass.
 */
export function retentionCutoff(retentionDays: number, now: Date): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - retentionDays * MS_PER_DAY));
}

