/**
 * Next per-project issue number. Archived issues keep their number, and a
 * purged issue's number stays reserved, so the max covers every remaining row
 * and every number the project has ever issued.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();

  const watermark = getDb()
    .select({ highestNumber: issueNumberWatermarks.highestNumber })
    .from(issueNumberWatermarks)
    .where(
      and(
        orgPredicate(issueNumberWatermarks.orgId, orgId),
        eq(issueNumberWatermarks.projectId, projectId),
      ),
    )
    .get();

