/**
 * Temporary coverage for restore and the retention purge. Deleted after the run.
 */
import { eq } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { getPlanLimits } from "@/config/plan-limits";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { RestoreRefusedError, retentionCutoff } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { toAppError } from "@/lib/errors";
import { getDb, issues } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import { NotFoundError } from "@/server/services/_support";
import { registerSearchListeners } from "@/server/services/search-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { IssueId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Array<() => void> = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(registerActivityListeners());
  detachers.push(registerSearchListeners());
  detachers.push(registerUsageListeners());
  tenant = await createTenant("trash", "free");
  await usageRepo.getUsage(tenant.org.id);
});

afterAll(() => {
  for (const off of detachers) off();
  cleanup();
});

function backdate(issueId: IssueId, archivedAt: string): void {
  getDb()
    .update(issues)
    .set({ archivedAt })
    .where(eq(issues.id, issueId))
    .run();
}

describe("restoreIssue", () => {
  it("restores the original number and publishes issue.restored", async () => {
    const seen: string[] = [];
    const off = subscribe("issue.restored", (payload) => {
      seen.push(payload.issueId);
    });

    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Bring me back" }),
    );
    const before = await usageRepo.getUsage(tenant.org.id);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, created.id);
    const archivedUsage = await usageRepo.getUsage(tenant.org.id);
    expect(archivedUsage.issuesUsed).toBe(before.issuesUsed - 1);

    const restored = await issueService.restoreIssue(
      tenant.actors.member,
      tenant.org.id,
      created.id,
    );

    expect(restored.number).toBe(created.number);
    expect(restored.archivedAt).toBeNull();
    expect(seen).toEqual([created.id]);

    const stored = await issueRepo.findIssueById(tenant.org.id, created.id);
    expect(stored?.archivedAt).toBeNull();
    expect(stored?.number).toBe(created.number);

    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.issuesUsed).toBe(before.issuesUsed);

    const hits = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "Bring me back",
      kinds: ["issue"],
      limit: 10,
      cursor: null,
    });
    expect(hits.items.map((row) => row.subjectId)).toContain(created.id);

    const activity = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "issue",
      created.id,
    );
    expect(activity.map((row) => row.action)).toContain("issue.restored");

    off();
  });

  it("refuses a live issue without writing or publishing", async () => {
    const live = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Still live" }),
    );
    const seen: string[] = [];
    const off = subscribe("issue.restored", (payload) => {
      seen.push(payload.issueId);
    });

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, live.id),
    ).rejects.toMatchObject({ name: "RestoreRefusedError", reason: "not_archived", code: "conflict" });

    expect(seen).toEqual([]);
    const stored = await issueRepo.findIssueById(tenant.org.id, live.id);
    expect(stored?.archivedAt).toBeNull();
    expect(toAppError(new RestoreRefusedError("not_archived")).code).toBe("conflict");
    off();
  });

  it("refuses an expired archive and an archived project, in that order", async () => {
    const expired = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Too old" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, expired.id);
    backdate(expired.id, "2000-01-01T00:00:00.000Z");

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, expired.id),
    ).rejects.toMatchObject({ reason: "expired" });
    expect((await issueRepo.findIssueById(tenant.org.id, expired.id))?.archivedAt).toBe(
      "2000-01-01T00:00:00.000Z",
    );

    const project = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Shelved",
      slug: "shelved",
      key: "SHLV",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const inside = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project.id, { title: "Under a shelf" }),
    );
    await issueService.archiveIssue(tenant.actors.admin, tenant.org.id, inside.id);
    await projectRepo.archiveProject(tenant.org.id, project.id);

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, inside.id),
    ).rejects.toMatchObject({ reason: "project_archived" });

    backdate(inside.id, "2000-01-01T00:00:00.000Z");
    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, inside.id),
    ).rejects.toMatchObject({ reason: "expired" });
  });

  it("refuses when the live count is already at the plan quota", async () => {
    const quotaProject = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Full",
      slug: "full",
      key: "FULL",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const archived = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, quotaProject.id, { title: "Waiting room" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    const limit = getPlanLimits("free").issuesPerProject;
    for (let number = 2; number <= limit + 1; number += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, quotaProject.id, { title: `Seat ${number}` }),
        tenant.actors.member.userId,
        number,
      );
    }

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, archived.id),
    ).rejects.toBeInstanceOf(RestoreRefusedError);
    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, archived.id),
    ).rejects.toMatchObject({ reason: "quota" });
    expect((await issueRepo.findIssueById(tenant.org.id, archived.id))?.archivedAt).not.toBeNull();
  });

  it("lets the author restore with a viewer role and rejects everyone else", async () => {
    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const authored = await issueRepo.insertIssue(
