 * comments go with it, and the storage counter gives back the megabytes those
 * attachments were charged. Issue numbers are not reused. The audit-log purge
30→ * past the same cut-off is unchanged. Archived issues are already out of the
 * issues-used counter, so that counter is left alone.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

