const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Soft-delete conventions.
 *
 * Archiving stamps `archived_at` instead of removing the row. An archived
 * issue stays restorable until the workspace plan's `retentionDays` have
 * elapsed (a multiple of 24h); the retention sweep then deletes it for good.
